const https = require('https');
const http = require('http');
const dns = require('dns');
const { URL } = require('url');

// Internal service client for fetching configuration from trusted partners
class ConfigFetcher {
  constructor(allowedDomains) {
    this.allowedDomains = allowedDomains;
    this.cache = new Map();
  }

  isAllowedDomain(hostname) {
    // Validate against allowlist of partner domains
    return this.allowedDomains.some(domain => {
      return hostname === domain || hostname.endsWith('.' + domain);
    });
  }

  async fetchConfig(configUrl) {
    const parsed = new URL(configUrl);

    // Security check: only allow HTTPS from approved partners
    if (parsed.protocol !== 'https:') {
      throw new Error('Only HTTPS URLs are permitted');
    }

    // Security check: domain allowlist
    if (!this.isAllowedDomain(parsed.hostname)) {
      throw new Error(`Domain ${parsed.hostname} is not in the allowlist`);
    }

    // Resolve DNS to check for private IPs (anti-SSRF)
    const addresses = await this.resolveDNS(parsed.hostname);

    // First resolution check passes - domain points to public IP
    if (this.isPrivateIP(addresses[0])) {
      throw new Error('Resolved to private IP range - blocked');
    }

    // TOCTOU gap: DNS may resolve differently on actual connection
    // The http module will re-resolve the hostname
    return new Promise((resolve, reject) => {
      const req = http.get({
        hostname: parsed.hostname,
        port: 80,
        path: parsed.pathname + '?metadata=true',
        headers: { 'Host': parsed.hostname },
        timeout: 5000
      }, (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => resolve(JSON.parse(data)));
      });
      req.on('error', reject);
    });
  }

  resolveDNS(hostname) {
    return new Promise((resolve, reject) => {
      dns.resolve4(hostname, (err, addresses) => {
        if (err) reject(err);
        else resolve(addresses);
      });
    });
  }

  isPrivateIP(ip) {
    const parts = ip.split('.').map(Number);
    // Check RFC1918 ranges
    if (parts[0] === 10) return true;
    if (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) return true;
    if (parts[0] === 192 && parts[1] === 168) return true;
    if (parts[0] === 127) return true;
    // Note: 169.254.169.254 is link-local, checked separately
    if (parts[0] === 169 && parts[1] === 254) return true;
    return false;
  }
}

// Lambda handler
exports.handler = async (event) => {
  const fetcher = new ConfigFetcher([
    'config.partner-integrations.io',
    'api.trusted-vendor.com',
    'feeds.data-provider.net'
  ]);

  try {
    const configUrl = event.queryStringParameters?.config_url;
    if (!configUrl) {
      return { statusCode: 400, body: 'Missing config_url parameter' };
    }

    const config = await fetcher.fetchConfig(configUrl);
    return {
      statusCode: 200,
      body: JSON.stringify({ status: 'ok', config })
    };
  } catch (err) {
    return {
      statusCode: 500,
      body: JSON.stringify({ error: err.message })
    };
  }
};
